/**
 * Infrastructure reference, generated by terraform-docs from the OpenTofu
 * root stack and modules under infra/. The terraform-docs version is pinned
 * so local and CI output match byte for byte.
 */

import { DocsScriptError, GENERATED_BANNER, REPO_ROOT } from "../lib";

import type { Generated } from "./types";

export const TERRAFORM_DOCS_VERSION = "0.24.0";

interface StackDescription {
  readonly path: string;
  readonly title: string;
  readonly summary: string;
}

const STACKS: readonly StackDescription[] = [
  {
    path: "infra",
    title: "Root stack (`infra/`)",
    summary:
      "One instance per environment, selected with `environments/<env>.tfvars` and `environments/<env>-backend.hcl`. Composes the shared and per-environment service modules.",
  },
  {
    path: "infra/modules/mcp-shared",
    title: "Shared module (`infra/modules/mcp-shared`)",
    summary:
      "Resources shared by every environment: IAM, the container registry, the public load balancer, and WAF.",
  },
  {
    path: "infra/modules/mcp-service",
    title: "Service module (`infra/modules/mcp-service`)",
    summary: "One ECS Fargate service per environment, with its networking, scaling, and alarms.",
  },
];

function spawn(args: readonly string[]): Bun.SyncSubprocess<"pipe", "pipe"> {
  try {
    return Bun.spawnSync(["terraform-docs", ...args], {
      cwd: REPO_ROOT,
      stdout: "pipe",
      stderr: "pipe",
    });
  } catch {
    throw new DocsScriptError(
      `terraform-docs ${TERRAFORM_DOCS_VERSION} is required to generate docs/reference/infrastructure.md (https://terraform-docs.io/user-guide/installation/)`,
    );
  }
}

function run(args: readonly string[]): string {
  const result = spawn(args);
  if (result.exitCode !== 0) {
    throw new DocsScriptError(`terraform-docs failed: ${result.stderr.toString().trim()}`);
  }
  return result.stdout.toString();
}

function assertVersion(): void {
  const output = run(["--version"]);
  if (!output.includes(`v${TERRAFORM_DOCS_VERSION} `)) {
    throw new DocsScriptError(
      `terraform-docs v${TERRAFORM_DOCS_VERSION} is required, found: ${output.trim()}`,
    );
  }
}

function stackDocs(path: string): string {
  return run([
    "markdown",
    "table",
    "--anchor=false",
    "--indent",
    "3",
    "--hide",
    "providers",
    "--sort-by",
    "required",
    path,
  ]).trim();
}

export function generateInfrastructure(): Generated {
  assertVersion();
  const sections: string[] = [
    GENERATED_BANNER,
    "",
    "# Infrastructure",
    "",
    "OpenTofu configuration for the deployed service. One MCP service runs per environment (see [ADR-001](../adr/ADR-001-one-mcp-service-per-environment.md)). Environment values live in `infra/environments/`, not here.",
  ];
  for (const stack of STACKS) {
    sections.push("", `## ${stack.title}`, "", stack.summary, "", stackDocs(stack.path));
  }
  sections.push("");
  return {
    files: [{ path: "docs/reference/infrastructure.md", content: sections.join("\n") }],
    regions: [],
  };
}
